  struct Candidate{uint32_t id;BottomTrial t;};std::vector<Candidate>scored;std::ostringstream c,e,out;uint64_t diagnostic_requests=0;unsigned diagnostic_trials=0;BottomTrial single=actual;std::vector<uint32_t>single_seeds=current;
