  std::sort(scored.begin(),scored.end(),[&](const Candidate&a,const Candidate&b){bool sa=a.t.hits>=actual.hits,sb=b.t.hits>=actual.hits;if(sa!=sb)return sa>sb;if(a.t.ios!=b.t.ios)return a.t.ios<b.t.ios;if(a.t.hits!=b.t.hits)return a.t.hits>b.t.hits;return a.id<b.id;});
  BottomTrial best4=actual;std::vector<uint32_t>best4seeds=current,combo;
  for(unsigned step=0;step<4;++step){bool found=false;BottomTrial best;uint32_t chosen=UINT32_MAX;for(unsigned j=0;j<std::min(size_t(8),scored.size());++j){auto id=scored[j].id;if(std::find(combo.begin(),combo.end(),id)!=combo.end())continue;auto proposed=combo;proposed.push_back(id);auto t=trial(proposed);diagnostic_requests+=t.ios;++diagnostic_trials;if(t.hits>=actual.hits&&(!found||t.ios<best.ios||(t.ios==best.ios&&t.hits>best.hits))){best=t;chosen=id;found=true;}}if(!found)break;combo.push_back(chosen);if(combo.size()==4&&better(best,best4)){best4=best;best4seeds=combo;}}
